import XCTest

final class TapFeedsTests: XCTestCase {
    func testOpenFeedsTab() throws {
        let springboard = XCUIApplication(bundleIdentifier: "com.apple.springboard")
        let cancel = springboard.buttons["Cancel"]
        if cancel.waitForExistence(timeout: 3) { cancel.tap() }

        let app = XCUIApplication(bundleIdentifier: "xyz.blueskyweb.app")
        app.activate()
        let predicate = NSPredicate(format: "label BEGINSWITH 'Feeds'")
        let matches = app.descendants(matching: .any).matching(predicate)
        XCTAssertTrue(matches.firstMatch.waitForExistence(timeout: 15))
        let screen = app.frame
        var target: XCUIElement?
        for i in 0..<matches.count {
            let el = matches.element(boundBy: i)
            let f = el.frame
            print("FEEDS_CANDIDATE \(i) type=\(el.elementType.rawValue) label=\(el.label) frame=\(f)")
            if f.minX >= screen.minX && f.maxX <= screen.maxX && f.minY >= screen.minY && f.maxY <= screen.maxY && target == nil {
                target = el
            }
        }
        guard let tab = target else {
            XCTFail("No on-screen Feeds element")
            return
        }
        let f = tab.frame
        let origin = app.coordinate(withNormalizedOffset: CGVector(dx: 0, dy: 0))
        origin.withOffset(CGVector(dx: f.midX - screen.minX, dy: f.midY - screen.minY)).tap()
        sleep(2)
        let shot = XCTAttachment(screenshot: XCUIScreen.main.screenshot())
        shot.lifetime = .keepAlways
        add(shot)
    }
}
EOF
